      }
      return Object.assign(base, { route: 'reply', understood: false, unknown: true, state: st === 'idle' ? 'idle' : st, context: cx,
        messages: [notUnderstoodMessage(ctx, ir.injection_suspected ? ir.reply : ir.reply)] });
    }
  }
